from typing import List, Dict; exec("class Solution:\n    def tokenize_numbers(self, numbers, vocab):\n        result = []\n        for num in numbers:\n            s = str(num)\n            tokens = []\n            i = 0\n            while i < len(s):\n                best = None\n                for j in range(len(s), i, -1):\n                    if s[i:j] in vocab:\n                        best = s[i:j]\n                        break\n                if best is None:\n                    best = s[i]\n                tokens.append(best)\n                i += len(best)\n            result.append(tokens)\n        return result\n    def count_tokens(self, text, vocab):\n        i = 0\n        count = 0\n        while i < len(text):\n            best = None\n            for j in range(len(text), i, -1):\n                if text[i:j] in vocab:\n                    best = text[i:j]\n                    break\n            if best is None:\n                best = text[i]\n            count += 1\n            i += len(best)\n        return count\n    def fertility_score(self, text, vocab):\n        words = text.split()\n        total_tokens = self.count_tokens(text, vocab)\n        score = total_tokens / len(words)\n        return round(score, 4)")